// Extrae la imagen generada (base64) de la respuesta de Gemini y prepárala para subir a storage
const resp = $input.first().json;
const part = resp.candidates?.[0]?.content?.parts?.find(p => p.inline_data);
return [{ json: { generated_image_base64: part?.inline_data?.data || null } }];
